// TypeScript Version: 4.1

/**
* Computes the modified Bessel function of the second kind of order one.
*
* ## Notes
*
* -   The function has a pole at `x = 0` (behaves like `1/x`).
* -   Accuracy for subnormal `x` is very poor. Full accuracy is achieved at approximately
*     `1.0e-308` but degrades rapidly as `x → 0`.
*
* @param x - input value
* @returns evaluated Bessel function
*
* @example
* var v = k1( 0.0 );
* // returns Infinity
*
* @example
* var v = k1( 1.0 );
* // returns ~0.6019
*
* @example
* var v = k1( 5.0 );
* // returns ~0.004045
*
* @example
* var v = k1( -1.0 );
* // returns NaN
*
* @example
* var v = k1( Infinity );
* // returns 0.0
*
* @example
* var v = k1( NaN );
* // returns NaN
*/
declare function k1( x: number ): number;

export = k1;
